package org.sleepwell.app;
import android.content.Context;import android.net.Uri;import android.os.*;import java.io.*;import java.lang.ref.WeakReference;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import java.util.function.BooleanSupplier;
/** Retained export operation. Destination access occurs only after a fresh explicit SAF result. */
final class LibraryAudioExportJob implements AutoCloseable {
 enum Phase{LOADING,READY,CHOOSING,WRITING,CANCELLING,DONE,ERROR}
 static final class State{final Phase phase;final LibraryAudioArchive.Plan plan;final String message;State(Phase phase,LibraryAudioArchive.Plan plan,String message){this.phase=phase;this.plan=plan;this.message=message;}}
 interface Observer{void changed(State state);}
 private static final Executor CANCEL=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(1),r->{Thread t=new Thread(r,"library-export-cancel");t.setDaemon(true);return t;},new ThreadPoolExecutor.DiscardPolicy());
 final Context app;final Records.Factory records;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();final AtomicReference<CancellationSignal> signal=new AtomicReference<>();final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();
 private WeakReference<Observer> observer=new WeakReference<>(null);private volatile State state=new State(Phase.LOADING,null,"");private volatile boolean closed,cancelled;
 LibraryAudioExportJob(Context context,Records.Factory factory,boolean interrupted){app=context.getApplicationContext();records=factory;load(interrupted?"Previous export was interrupted. Review again and choose a fresh save location.":"");}
 State state(){return state;}void observe(Observer value){if(closed)return;observer=new WeakReference<>(value);value.changed(state);}void detach(Observer value){if(observer.get()==value)observer.clear();}
 private void publish(State value){if(closed)return;state=value;Observer target=observer.get();if(target!=null)target.changed(value);}
 void refresh(){if(closed||state.phase==Phase.LOADING||state.phase==Phase.WRITING||state.phase==Phase.CANCELLING||state.phase==Phase.CHOOSING)return;load("");}
 private static String detail(Exception failure){String text=failure.getMessage();if(text!=null&&text.length()<320)for(String prefix:new String[]{"The library","Library metadata","End tracking","An unfinished","Finish pending","A saved","A recording","A sound event","There are no","Another audio export","Private export"})if(text.startsWith(prefix))return text;return "A recording or its source metadata is unavailable. Review the library and try again.";}
 private void load(String message){cancelled=false;publish(new State(Phase.LOADING,null,message));worker.execute(()->{try(Store store=records.open(app)){LibraryAudioArchive.Plan plan=LibraryAudioArchive.prepare(app,store,()->!closed&&!cancelled);String result=plan.audio.isEmpty()?"There are no saved recordings to export.":message;main.post(()->publish(new State(Phase.READY,plan,result)));}catch(Exception error){String failure=detail(error);main.post(()->publish(new State(Phase.ERROR,null,failure)));}});}
 boolean choose(){State before=state;if(closed||before.plan==null||before.plan.audio.isEmpty()||before.phase!=Phase.READY&&before.phase!=Phase.DONE)return false;publish(new State(Phase.CHOOSING,before.plan,"Choose a new ZIP destination in Android Files."));return true;}
 void cancelChoice(){if(state.phase==Phase.CHOOSING)publish(new State(Phase.READY,state.plan,"Save location cancelled. No audio was written."));}
 void write(Uri destination){if(closed||state.phase!=Phase.CHOOSING||state.plan==null)return;if(destination==null||!"content".equals(destination.getScheme())){publish(new State(Phase.ERROR,state.plan,"Choose an Android document destination, then refresh the review."));return;}LibraryAudioArchive.Plan plan=state.plan;cancelled=false;publish(new State(Phase.WRITING,plan,"Staging a private snapshot, then writing the ZIP…"));worker.execute(()->{BooleanSupplier active=()->!closed&&!cancelled;try{LibraryAudioArchive.Snapshot prepared;try(Store store=records.open(app)){prepared=LibraryAudioArchive.stage(app,store,plan,active);}try(LibraryAudioArchive.Snapshot snapshot=prepared){NightAudioArchive.active(active);CancellationSignal cancellation=new CancellationSignal();signal.set(cancellation);try{NightAudioArchive.active(active);ParcelFileDescriptor file=app.getContentResolver().openFileDescriptor(destination,"wt",cancellation);if(file==null)throw new IOException("Destination unavailable");descriptor.set(file);try(OutputStream output=new ParcelFileDescriptor.AutoCloseOutputStream(file)){NightAudioArchive.active(active);snapshot.write(output,active);}finally{descriptor.compareAndSet(file,null);}}finally{signal.compareAndSet(cancellation,null);}}NightAudioArchive.active(active);main.post(()->publish(new State(Phase.DONE,plan,"Library ZIP exported. Audio and manifest were closed successfully. The ZIP includes metadata for the reviewed restore flow.")));}catch(Exception error){String failure=cancelled?"Export cancelled. The destination may contain a partial file; remove it before retrying.":"Export failed. The destination may contain a partial file. "+detail(error);main.post(()->publish(new State(Phase.ERROR,plan,failure)));}});}
 void cancelExport(){if(state.phase!=Phase.WRITING)return;cancelled=true;publish(new State(Phase.CANCELLING,state.plan,"Cancelling and closing the destination…"));cancelNative();}
 private void cancelNative(){ParcelFileDescriptor file=descriptor.get();CancellationSignal cancellation=signal.get();CANCEL.execute(()->{if(file!=null)try{file.close();}catch(IOException ignored){}if(cancellation!=null)cancellation.cancel();});}
 public void close(){if(closed)return;closed=true;cancelled=true;observer.clear();cancelNative();worker.shutdownNow();}
}
